def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_defects = 0
    my_defects = 0
    for a, b in history:
        if b == 'D':
            opp_defects += 1
        if a == 'D':
            my_defects += 1
    last_my, last_opp = history[-1]
    remaining = 100 - n

    if remaining <= 1:
        return 'D'

    if n < 5:
        return 'C'
    if n == 5:
        return 'D'
    if n == 6:
        if opp_defects <= 1:
            return 'C'
        return 'D'

    coop_after_my_def = 0
    total_after_my_def = 0
    for i in range(1, n):
        if history[i-1][0] == 'D':
            total_after_my_def += 1
            if history[i][1] == 'C':
                coop_after_my_def += 1

    exploitable = False
    if total_after_my_def >= 1:
        if coop_after_my_def * 5 >= total_after_my_def * 4:
            if opp_defects * 5 <= n:
                exploitable = True

    if exploitable:
        recent_opp_def = 0
        start = max(0, n - 3)
        for i in range(start, n):
            if history[i][1] == 'D':
                recent_opp_def += 1
        if recent_opp_def == 0:
            return 'D'

    if opp_defects * 2 > n:
        return 'D'

    if last_opp == 'D':
        if opp_defects * 3 <= n and n >= 8:
            return 'C'
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        return 'D'

    if last_my == 'D':
        return 'C'
    return 'C'
